// === Tab: mySketch ===
ArrayList<Particle> particles;

let xoff, yoff, zoff, inc, col;

let spread, cols, rows, num;
let offset = 2;

let img;
let vectors;

function preload() {


}

function setup() {
	img = loadImage("https://openprocessing.org/sketch/1526762/files/mitzi-bw.jpg"); 
  createCanvas(736, 500);

  background(0);
  frameRate(100);
  init();
}


function init() {

  spread  = 10;
  inc  = random(0.1,0.8);
  num  = 4000;
  col  = random(255);
  cols = floor(width / spread) + 1;
  rows = floor(height / spread) + 1;
  vectors   = new Array(cols * rows);
  particles = new ArrayList<Particle>();

  for (i=0; i<num; i++)
    particles.add(new Particle());
}

function draw() {
  fill(0,20);
  rect(0,0,width,height);
  filter(DILATE,2);

  yoff = 0;
  for (y = 0; y < rows; y++) {
    xoff = 0;
    for (x = 0; x < cols; x++) {
      let angle = noise(xoff, yoff, zoff) * TWO_PI * 2;
      let v = PVector.fromAngle(angle);
      v.setMag(1);
      vectors[x + y * cols] = v;
      xoff += inc;
    }
    yoff += inc;
  }
  zoff += 0.0005;
  if (col < 255)col += 0.5;
  else col = 0;
  for (let p of particles)p.run();
}
function mousePressed()
{
  background(255);
  init();
}

// === Tab: tab2 ===
class Particle {
  pos, vel, acc, prev;
  let max = random(2, 8);


  constructor() {
    pos  = new PVector(width/2, height/2);
    prev = new PVector(pos.x, pos.y);
    vel  = new PVector(0, 0);
    acc  = new PVector(0, 0);
  }


  function copy() {
    prev.x = pos.x;
    prev.y = pos.y;
  }


  function run() {
    follow();
    update();
    show();
  }


  function update() {
    pos.add(vel);
    vel.limit(max);
    vel.add(acc);
    acc.mult(0);
    if (pos.x > width) {
      pos.x = 0; 
      copy();
    }  
    if (pos.x < 0) {
      pos.x = width; 
      copy();
    } 
    if (pos.y > height) {
      pos.y = 0; 
      copy();
    }  
    if (pos.y < 0) {
      pos.y = height; 
      copy();
    }
  }
  function follow() {
    let x = floor(pos.x / spread);
    let y = floor(pos.y / spread);
    let force = vectors[x + y * cols];
    acc.add(force);
  }
  function show() {
   let c = img.get(int(pos.x),int(pos.y));
   stroke(c);
   line(pos.x, pos.y, prev.x, prev.y);

       copy();
  }
}

